import numpy as np
SP = 4.0 * 0.13957 ** 2
SIN = 4.0 * 0.493677 ** 2
def _scal(value):
    arr = np.atleast_1d(np.asarray(value, dtype=complex)).ravel()
    idx = np.arange(1.0, arr.size + 1.0)
    return float(np.sum(np.abs(arr))
                 + np.sum(arr.real * np.cos(idx))
                 + np.sum(arr.imag * np.sin(idx)))
def _threshold(s, sp, sin, sheet):
    return map_two_threshold_variable(s, sp, sin, sheet)
def _lhc(point, edge, centre):
    return map_left_hand_cut(point, edge, centre)
def _toy_threshold(s, sp, sin, sheet):
    base = (complex(s) - sp) / (sin + 3.0 * abs(s) + 1.0)
    scale = {'11': 1.0, '21': -1.0, '22': 4.0, '12': -4.0}[sheet]
    return scale * (0.3 + base)
def _toy_lhc(point, edge, centre):
    return (complex(point) - centre) / (1.0 - edge * complex(point))
assert np.allclose(_scal(map_four_sheet_variable(-2.0, SP, SIN, 0.0, -0.30, '11', _threshold, _lhc)), target)

